12	// This file pins the distinction between a clean end of input and a reader
13	// failure mid-record. At clean EOF the last unterminated (but otherwise
14	// complete) line is still a record; after a non-EOF read error only lines
15	// whose newline has already been received are records, even when the line and
16	// the error came back from the same Read. The unread-looking tail must never
17	// become an event, watermark or idle declaration, and so can never produce a
18	// late notice or a window result; the caller gets the reader's own error
19	// through errors.Is.
20	
21	// collectedLine is one line handed to the readAggregateLines callback.
22	type collectedLine struct {
23		text string
24		no   int
25	}
26	
27	func collectLines(t *testing.T, r io.Reader) ([]collectedLine, error) {
28		t.Helper()
29		var got []collectedLine
30		err := readAggregateLines(r, func(line string, lineNo int) error {
31			got = append(got, collectedLine{text: line, no: lineNo})
32			return nil
33		})
34		return got, err
35	}
