339					if !errors.Is(err, errSentinelChunkedRead) {
340						t.Fatalf("error = %T %v, want the reader's original error via errors.Is", err, err)
341					}
342					if _, ok := err.(*InputError); ok {
343						t.Fatalf("read failure must not be masked by a JSON/input error: %v", err)
344					}
345					if out.String() != "" {
346						t.Fatalf("unterminated watermark must not close a window, stdout = %q", out.String())
347					}
